let __v_179 = pyrt::literals::decode("{\"$tuple\":[\"size\",\"what size\",\"how big\",\"how much\",\"how many\",\"how long\",\"price\",\"cost\",\"costs\",\"cheap\",\"cheapest\",\"buy\",\"buying\",\"bought\",\"which\",\"best\",\"recommend\",\"worth\",\"broken\",\"broke\",\"not working\",\"repair\",\"fix\",\"mend\",\"rusty\",\"rust\",\"clean\",\"cleaning\",\"wash\",\"instead\",\"substitute\",\"swap\",\"dont have\",\"don't have\",\"havent got\",\"haven't got\",\"without\",\"no\",\"i need a\",\"should i get\",\"shall i buy\",\"recipe\",\"recipes\",\"how do i use\",\"how to use\",\"how do i\",\"how to\",\"in the dishwasher\",\"dishwasher\",\"oven safe\",\"microwave\",\"think\",\"thought\",\"opinion\",\"good\",\"any good\",\"rate\",\"any cop\",\"what do i do\",\"what should i do\",\"help\",\"bite\",\"bites\",\"bitten\",\"sting\",\"stung\",\"plant\",\"plants\",\"crab\",\"tarantula\",\"black widow\",\"web\",\"webs\",\"mite\",\"mites\",\"daddy long legs\",\"huntsman\",\"money spider\",\"house spider\",\"garden spider\",\"houseplant\",\"houseplants\"]}")?;
